window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c34c2b817f0880f"]={"versions": [{"id": "FIG-1c34c2b817f0880f", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des generischen Dokumentenstruktur-Metamodells in AUTOSAR (Template Generic Structure Template). Dargestellt ist die Metamodellstruktur für mehrsprachige Abbildungen (<code>MlFigure</code>) einschließlich Bildbeschriftung, sprachspezifischer Grafikdateien sowie Bildkartenbereichen (Image Maps).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MlFigure</code>: Repräsentiert die logische Abbildung; spezialisiert bzw. implementiert das Konzept <code>Paginateable</code>.\n</li><li><code>Caption</code>: Repräsentiert die Bildunterschrift bzw. Beschriftung; spezialisiert <code>MultilanguageReferrable</code>.\n</li><li><code>MlFigure</code> besitzt eine gerichtete Komposition zu <code>Caption</code> über die Assoziationsrolle <code>+figureCaption</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>LGraphic</code>: Repräsentiert eine sprachspezifische Ausprägung der Grafik; spezialisiert <code>LanguageSpecific</code>.\n</li><li><code>MlFigure</code> aggregiert bzw. komponiert <code>LGraphic</code> über die Assoziationsrolle <code>+lGraphic</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>Graphic</code>: Repräsentiert das physische Grafikobjekt; spezialisiert <code>EngineeringObject</code> und trägt das Stereotyp/Attribut <code>A</code>.\n</li><li><code>LGraphic</code> komponiert <code>Graphic</code> über die Rolle <code>+graphic</code> mit der festen Multiplizität <code>1</code>.\n</li><li><code>Map</code>: Repräsentiert eine klickbare oder referenzierbare Bildkarte (Client-Side Image Map).\n</li><li><code>LGraphic</code> komponiert <code>Map</code> über die Assoziationsrolle <code>+map</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>Area</code>: Repräsentiert ein einzelnes geometrisches Teilgebiet innerhalb einer <code>Map</code>.\n</li><li><code>Map</code> komponiert <code>Area</code> über die Assoziationsrolle <code>+area</code> mit der Multiplizität <code>1..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm definiert das Schaubild kein dynamisches Ablaufverhalten oder Nachrichtensequenzen zur Laufzeit. Es bestimmt die strukturelle Schachtelung und Instanziierungsregeln bei der Serialisierung von XML- bzw. ARXML-Modellbeschreibungen im Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler gelten folgende normative Strukturvorgaben:</p>\n<ul class=\"fig-list\"><li>Eine <code>MlFigure</code> kann optional maximal eine Bildunterschrift (<code>+figureCaption</code>, <code>0..1</code>) besitzen.\n</li><li>Eine <code>MlFigure</code> kann beliebig viele sprachspezifische Repräsentationen (<code>+lGraphic</code>, <code>0..*</code>) einbetten.\n</li><li>Jedes <code>LGraphic</code>-Element muss zwingend genau ein konkretes Grafikobjekt (<code>+graphic</code>, <code>1</code>) referenzieren bzw. beinhalten.\n</li><li>Optional kann einem <code>LGraphic</code> höchstens eine Bildkarte (<code>+map</code>, <code>0..1</code>) zugeordnet werden.\n</li><li>Sofern ein <code>Map</code>-Element definiert ist, muss dieses aus mindestens einem Teilbereich (<code>+area</code>, <code>1..*</code>) bestehen.\n</li></ul>"}, {"id": "FIG-3384b7dfdd76f9b0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des generischen Dokumentenstruktur-Metamodells in AUTOSAR (Template Generic Structure Template). Dargestellt ist die Metamodellstruktur für mehrsprachige Abbildungen (<code>MlFigure</code>) einschließlich Bildbeschriftung, sprachspezifischer Grafikdateien sowie Bildkartenbereichen (Image Maps).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MlFigure</code>: Repräsentiert die logische Abbildung; spezialisiert bzw. implementiert das Konzept <code>Paginateable</code>.\n</li><li><code>Caption</code>: Repräsentiert die Bildunterschrift bzw. Beschriftung; spezialisiert <code>MultilanguageReferrable</code>.\n</li><li><code>MlFigure</code> besitzt eine gerichtete Komposition zu <code>Caption</code> über die Assoziationsrolle <code>+figureCaption</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>LGraphic</code>: Repräsentiert eine sprachspezifische Ausprägung der Grafik; spezialisiert <code>LanguageSpecific</code>.\n</li><li><code>MlFigure</code> aggregiert bzw. komponiert <code>LGraphic</code> über die Assoziationsrolle <code>+lGraphic</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>Graphic</code>: Repräsentiert das physische Grafikobjekt; spezialisiert <code>EngineeringObject</code> und trägt das Stereotyp/Attribut <code>A</code>.\n</li><li><code>LGraphic</code> komponiert <code>Graphic</code> über die Rolle <code>+graphic</code> mit der festen Multiplizität <code>1</code>.\n</li><li><code>Map</code>: Repräsentiert eine klickbare oder referenzierbare Bildkarte (Client-Side Image Map).\n</li><li><code>LGraphic</code> komponiert <code>Map</code> über die Assoziationsrolle <code>+map</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>Area</code>: Repräsentiert ein einzelnes geometrisches Teilgebiet innerhalb einer <code>Map</code>.\n</li><li><code>Map</code> komponiert <code>Area</code> über die Assoziationsrolle <code>+area</code> mit der Multiplizität <code>1..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm definiert das Schaubild kein dynamisches Ablaufverhalten oder Nachrichtensequenzen zur Laufzeit. Es bestimmt die strukturelle Schachtelung und Instanziierungsregeln bei der Serialisierung von XML- bzw. ARXML-Modellbeschreibungen im Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler gelten folgende normative Strukturvorgaben:</p>\n<ul class=\"fig-list\"><li>Eine <code>MlFigure</code> kann optional maximal eine Bildunterschrift (<code>+figureCaption</code>, <code>0..1</code>) besitzen.\n</li><li>Eine <code>MlFigure</code> kann beliebig viele sprachspezifische Repräsentationen (<code>+lGraphic</code>, <code>0..*</code>) einbetten.\n</li><li>Jedes <code>LGraphic</code>-Element muss zwingend genau ein konkretes Grafikobjekt (<code>+graphic</code>, <code>1</code>) referenzieren bzw. beinhalten.\n</li><li>Optional kann einem <code>LGraphic</code> höchstens eine Bildkarte (<code>+map</code>, <code>0..1</code>) zugeordnet werden.\n</li><li>Sofern ein <code>Map</code>-Element definiert ist, muss dieses aus mindestens einem Teilbereich (<code>+area</code>, <code>1..*</code>) bestehen.\n</li></ul>"}, {"id": "FIG-45d646193362e4a9", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des generischen Dokumentenstruktur-Metamodells in AUTOSAR (Template Generic Structure Template). Dargestellt ist die Metamodellstruktur für mehrsprachige Abbildungen (<code>MlFigure</code>) einschließlich Bildbeschriftung, sprachspezifischer Grafikdateien sowie Bildkartenbereichen (Image Maps).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MlFigure</code>: Repräsentiert die logische Abbildung; spezialisiert das Konzept <code>Paginateable</code>.\n</li><li><code>Caption</code>: Repräsentiert die Bildunterschrift bzw. Beschriftung; spezialisiert <code>MultilanguageReferrable</code>.\n</li><li><code>MlFigure</code> besitzt eine gerichtete Komposition zu <code>Caption</code> über die Assoziationsrolle <code>+figureCaption</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert einen mehrsprachigen beschreibenden Übersichtsparagrafen für die Beschriftung.\n</li><li><code>Caption</code> komponiert <code>MultiLanguageOverviewParagraph</code> über die Rolle <code>+desc</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>LGraphic</code>: Repräsentiert eine sprachspezifische Ausprägung der Grafik; spezialisiert <code>LanguageSpecific</code>.\n</li><li><code>MlFigure</code> komponiert <code>LGraphic</code> über die Assoziationsrolle <code>+lGraphic</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>Graphic</code>: Repräsentiert das physische Grafikobjekt; spezialisiert <code>EngineeringObject</code> und trägt die Kennzeichnung <code>A</code>.\n</li><li><code>LGraphic</code> komponiert <code>Graphic</code> über die Rolle <code>+graphic</code> mit der Multiplizität <code>1</code>.\n</li><li><code>Map</code>: Repräsentiert eine Bildkarte (Image Map).\n</li><li><code>LGraphic</code> komponiert <code>Map</code> über die Assoziationsrolle <code>+map</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>Area</code>: Repräsentiert einen geometrischen Bereich innerhalb einer <code>Map</code>.\n</li><li><code>Map</code> komponiert <code>Area</code> über die Assoziationsrolle <code>+area</code> mit der Multiplizität <code>1..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm definiert das Schaubild kein dynamisches Ablaufverhalten oder Nachrichtensequenzen zur Laufzeit. Es bestimmt die strukturelle Schachtelung und Instanziierungsregeln bei der Serialisierung von XML- bzw. ARXML-Modellbeschreibungen im Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler gelten folgende normative Strukturvorgaben:</p>\n<ul class=\"fig-list\"><li>Eine <code>MlFigure</code> kann optional maximal eine Bildunterschrift (<code>+figureCaption</code>, <code>0..1</code>) enthalten.\n</li><li>Eine <code>Caption</code> darf optional eine zusätzliche Beschreibung in Form eines <code>MultiLanguageOverviewParagraph</code> (<code>+desc</code>, <code>0..1</code>) tragen.\n</li><li>Eine <code>MlFigure</code> kann beliebig viele sprachspezifische Repräsentationen (<code>+lGraphic</code>, <code>0..*</code>) einbetten.\n</li><li>Jedes <code>LGraphic</code>-Element muss zwingend genau ein konkretes Grafikobjekt (<code>+graphic</code>, <code>1</code>) enthalten.\n</li><li>Optional kann einem <code>LGraphic</code> höchstens eine Bildkarte (<code>+map</code>, <code>0..1</code>) zugeordnet werden.\n</li><li>Ist ein <code>Map</code>-Element vorhanden, muss es mindestens einen Bereich (<code>+area</code>, <code>1..*</code>) definieren.\n</li></ul>"}, {"id": "FIG-456541196a9c897d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des generischen Dokumentenstruktur-Metamodells in AUTOSAR (Template Generic Structure Template). Dargestellt ist die Metamodellstruktur für mehrsprachige Abbildungen (<code>MlFigure</code>) einschließlich Bildbeschriftung, sprachspezifischer Grafikdateien sowie Bildkartenbereichen (Image Maps).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>MlFigure</code>: Repräsentiert die logische Abbildung; spezialisiert das Konzept <code>Paginateable</code>.\n</li><li><code>Caption</code>: Repräsentiert die Bildunterschrift bzw. Beschriftung; spezialisiert <code>MultilanguageReferrable</code>.\n</li><li><code>MlFigure</code> besitzt eine gerichtete Komposition zu <code>Caption</code> über die Assoziationsrolle <code>+figureCaption</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert einen mehrsprachigen beschreibenden Übersichtsparagrafen für die Beschriftung.\n</li><li><code>Caption</code> komponiert <code>MultiLanguageOverviewParagraph</code> über die Rolle <code>+desc</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>LGraphic</code>: Repräsentiert eine sprachspezifische Ausprägung der Grafik; spezialisiert <code>LanguageSpecific</code>.\n</li><li><code>MlFigure</code> komponiert <code>LGraphic</code> über die Assoziationsrolle <code>+lGraphic</code> mit der Multiplizität <code>0..*</code>.\n</li><li><code>Graphic</code>: Repräsentiert das physische Grafikobjekt; spezialisiert <code>EngineeringObject</code> und trägt die Kennzeichnung <code>A</code>.\n</li><li><code>LGraphic</code> komponiert <code>Graphic</code> über die Rolle <code>+graphic</code> mit der Multiplizität <code>1</code>.\n</li><li><code>Map</code>: Repräsentiert eine Bildkarte (Image Map).\n</li><li><code>LGraphic</code> komponiert <code>Map</code> über die Assoziationsrolle <code>+map</code> mit der Kardinalität <code>0..1</code>.\n</li><li><code>Area</code>: Repräsentiert einen geometrischen Bereich innerhalb einer <code>Map</code>.\n</li><li><code>Map</code> komponiert <code>Area</code> über die Assoziationsrolle <code>+area</code> mit der Multiplizität <code>1..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm definiert das Schaubild kein dynamisches Ablaufverhalten oder Nachrichtensequenzen zur Laufzeit. Es bestimmt die strukturelle Schachtelung und Instanziierungsregeln bei der Serialisierung von XML- bzw. ARXML-Modellbeschreibungen im Generic Structure Template.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler gelten folgende normative Strukturvorgaben:</p>\n<ul class=\"fig-list\"><li>Eine <code>MlFigure</code> kann optional maximal eine Bildunterschrift (<code>+figureCaption</code>, <code>0..1</code>) enthalten.\n</li><li>Eine <code>Caption</code> darf optional eine zusätzliche Beschreibung in Form eines <code>MultiLanguageOverviewParagraph</code> (<code>+desc</code>, <code>0..1</code>) tragen.\n</li><li>Eine <code>MlFigure</code> kann beliebig viele sprachspezifische Repräsentationen (<code>+lGraphic</code>, <code>0..*</code>) einbetten.\n</li><li>Jedes <code>LGraphic</code>-Element muss zwingend genau ein konkretes Grafikobjekt (<code>+graphic</code>, <code>1</code>) enthalten.\n</li><li>Optional kann einem <code>LGraphic</code> höchstens eine Bildkarte (<code>+map</code>, <code>0..1</code>) zugeordnet werden.\n</li><li>Ist ein <code>Map</code>-Element vorhanden, muss es mindestens einen Bereich (<code>+area</code>, <code>1..*</code>) definieren.\n</li></ul>"}], "trans": [{"from": "FIG-1c34c2b817f0880f", "to": "FIG-3384b7dfdd76f9b0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3384b7dfdd76f9b0", "to": "FIG-45d646193362e4a9", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Klasse <code>MultiLanguageOverviewParagraph</code>\n</li><li>Ergänzung einer Kompositionsbeziehung von <code>Caption</code> zu <code>MultiLanguageOverviewParagraph</code> mit Rollenname <code>+desc</code> und Multiplizität <code>0..1</code>\n</li></ul>"}, {"from": "FIG-45d646193362e4a9", "to": "FIG-456541196a9c897d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
